package com.autoops.machine.service;
import com.autoops.machine.dto.MachineDtos; import com.autoops.machine.entity.Machine; import com.autoops.machine.repository.MachineRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class MachineService { private final MachineRepository repo; public MachineService(MachineRepository r){repo=r;} public List<MachineDtos.Response> list(long userId){return repo.findByCreatedByAndDeletedAtIsNull(userId).stream().map(this::dto).toList();} public MachineDtos.Response create(long userId,MachineDtos.Create x){Machine m=new Machine();m.setName(x.name());m.setHostname(x.hostname());m.setSshPort(x.sshPort()==null?22:x.sshPort());m.setOperatingSystem(x.operatingSystem());m.setOsVersion(x.osVersion());m.setCreatedBy(userId);return dto(repo.save(m));} private MachineDtos.Response dto(Machine m){return new MachineDtos.Response(m.getId(),m.getName(),m.getHostname(),m.getSshPort(),m.getOperatingSystem(),m.getOsVersion());} }
